const crypto = require('crypto');
const secret = $env.RTLS_WEBHOOK_SECRET;
if (!secret) throw new Error('RTLS_WEBHOOK_SECRET is not configured');
const signature = $json.headers?.['x-rtls-signature'] || '';
const rawBody = JSON.stringify($json.body);
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
const valid = signature.length === expected.length && crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected));
if (!valid) throw new Error('Invalid RTLS webhook signature');
return [{ json: $json.body }];
